section.listing:
      The per-voice drift step, simplified

/* Called once per control tick (every 1 ms) for each voice.
 * `amount` is the Drift knob, 0.0 to 1.0.                     */
float drift_step(voice_t *v, float amount, rng_t *rng)
{
    const float pull  = 0.0008f;          /* return-to-centre per tick   */
    const float step  = 0.045f * amount;  /* random step size, in cents  */
    const float limit = 12.0f  * amount;  /* hard ceiling, in cents      */

    v->drift += step * rng_gaussian(rng); /* wander...                   */
    v->drift -= pull * v->drift;          /* ...but drift home slowly    */

    if (v->drift >  limit) v->drift =  limit;
    if (v->drift < -limit) v->drift = -limit;

    return v->drift + v->tolerance;       /* tolerance never changes     */
}
